// Check daily quota
const cfg = $json;
const today = new Date().toISOString().slice(0, 10);
const countRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://auth.purama.dev/rest/v1/partner_emails?user_id=eq.${cfg.user_id}&type=in.(outreach,relance_1,relance_2,relance_3)&sent_at=gte.${today}T00:00:00&select=id`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Accept-Profile': 'purama_ai',
    Prefer: 'count=exact',
  },
  json: true,
  returnFullResponse: true,
});
const sentToday = (countRes.headers['content-range'] || '0/0').split('/')[1];
const remaining = Math.max(0, cfg.daily_outreach_limit - parseInt(sentToday, 10));
if (remaining === 0) return [{ json: { ...cfg, _skip: true, _sent_today: sentToday } }];
// Fetch ready prospects
const prosRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://auth.purama.dev/rest/v1/partner_prospects?user_id=eq.${cfg.user_id}&status=eq.ready_to_contact&email=not.is.null&order=ai_score.desc.nullslast&limit=${Math.min(remaining, 5)}`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Accept-Profile': 'purama_ai',
  },
  json: true,
});
if (!prosRes.length) return [{ json: { ...cfg, _skip: true } }];
return prosRes.map((p) => ({ json: { ...cfg, _prospect: p } }));
